export type ThemeModePreference = keyof typeof themeModeDescriptors;

export type ResolvedThemeMode = Exclude<ThemeModePreference, "system">;

export function resolveThemeMode(preference: ThemeModePreference, systemDark: boolean): ResolvedThemeMode {
  return preference === "system" ? (systemDark ? "dark" : "light") : preference;
}
